old:
    override fun delete(ids: Collection<String>) {
        if (ids.isEmpty()) return
        val list = ids.toList()
        scope.launch {
            runCatching { outboxDao()?.deleteByIds(list) }
                .onFailure { Log.w(TAG, "outbox delete failed: ${it.message}") }
        }
    }
}

